const item = $input.item.json;
const copies = (item.payload && item.payload.copies) || [];
const assets = (item.payload && item.payload.assets) || [];
const c = copies.find(x => x.channel === item.channel) || copies[0] || {};
const vid = (assets.find(a => a.type === 'video') || {}).url;
if (!vid) throw new Error('TikTok投稿には動画URL(assets type=video)が必要です');
const title = [c.body, (c.hashtags || []).join(' ')].filter(Boolean).join(' ').slice(0, 150);
return [{ json: { videoUrl: vid, title } }];

const r = $input.item.json;
const pid = (r.data && r.data.publish_id) || null;
return [{ json: { channel: 'tiktok-main', postId: pid, status: pid ? 'submitted' : 'unknown', raw: r } }];
